sp_widget.client_script:
api.controller=function($scope, $rootScope, spModal, spUtil) {
	/* widget controller */
	var c = this;

	$rootScope.$on('selectNote', function(event,data) 
								 {

		c.server.get({

			action:'getNoteRecord',
			noteID:$rootScope.noteID
		}).then(function(r) {

			c.data.note = r.data.notes.note;
			c.data.title = r.data.notes.title;
			c.data.noteID = r.data.notes.sys_id;

		});


	});

	c.updateNote = function(updateType) {

		c.server.get ({
			action: 'updateNote',
			noteID: c.data.noteID,
			title: c.data.title,
			note: c.data.note

		}).then(function(r) {

			if(updateType == 'title' || updateType == 'note') {
				$rooctScope.$emit('updatedNoteRec',r.data);

			}
		});

	}

	c.confirmDelete = function() {
		spModal.confirm("Are you sure yu want to delete the record ?").then(function(confirmed) {

			if(confirmed) {

				c.deletNote();
			}
		});


	}

	c.deletNote = function() {

		c.server.get ({
			action: 'deleteNote',
			noteID: c.data.noteID
		}).then(function(r) {
		spUtil.addTrivialMessage('The '+c.data.title+' record has been deleted');
			c.server.refresh();
			$rootScope.$emit('deleteNote',c.data.noteID);
			c.data.title = '';
			c.data.note = '';
			c.data.noteID = '';
	});


	}
}

sp_widget.script:
(function() {
	/* populate the 'data' object */
	/* e.g., data.table = $sp.getValue('table'); */

	if(input && input.action == 'getNoteRecord') {

		var noteRec = new GlideRecord('x_snc_createnotes_note');
		noteRec.addEncodedQuery('sys_id='+input.noteID);
		noteRec.query();

		if(noteRec.next()) {

			data.notes ={};

			$sp.getRecordValues(data.notes, noteRec, "title,sys_id,note");

		}
	}

	else if(input && input.action == 'updateNote') {

		var noteUpdateRec = new GlideRecord('x_snc_createnotes_note');
		if(noteUpdateRec.get(input.noteID)) {

			data.updateNote = {};


			noteUpdateRec.note = input.note;
			noteUpdateRec.title = input.title;
			noteUpdateRec.update();

			data.title = noteUpdateRec.getValue('title');
			data.note = noteUpdateRec.getValue('note').slice(0,20);
		}
	}


	else if(input && input.action == 'deleteNote') {

		var noteRec = new GlideRecord('x_snc_createnotes_note');

		if(noteRec.get(input.noteID)) {

			noteRec.deleteRecord();
		}
	}
})();
